function modal(title:string,content:string){$<HTMLDialogElement>('#modal').innerHTML=`<h2>${title}</h2>${content}<div class="actions">${btn('close-modal',t('إغلاق','Close'),'',true)}</div>`;$<HTMLDialogElement>('#modal').querySelectorAll<HTMLFormElement>('form').forEach(form=>ensureFormError(form));$<HTMLDialogElement>('#modal').showModal();}
function field(name:string,ar:string,en:string,type='text',required=false){return `<label>${t(ar,en)}<input name="${name}" type="${type}" ${type==='number'?'step="0.01" min="0"':''} ${required?'required':''} ${type==='password'?'minlength="4" autocomplete="new-password"':''}>${type==='password'?btn('toggle-password',t('إظهار كلمة المرور','Show password'),'',true):''}</label>`;}
