function invoiceForm(){if(!state.visits.length)return notify(t('سجل زيارة طبية أولًا','Record an encounter first'),true);quote=undefined;modal(t('فاتورة خدمات جديدة','New service invoice'),`<form id="invoice-form"><div class="formgrid"><label>${t('الزيارة','Encounter')}<select name="visit_id" id="invoice-visit">${state.visits.map(v=>`<option value="${esc(v.id)}">${esc(patientName(v.patient_id))} — ${dt(v.created_at)}</option>`).join('')}</select></label><label>${t('طريقة التسعير','Pricing')}<select name="plan_id"><option value="">${t('نقدي / خاص','Cash / private')}</option>${options(state.plans)}</select></label></div><div>${state.services.filter(s=>s.active!==0).map(s=>`<div class="checkrow"><input type="checkbox" name="service" value="${esc(s.id)}" aria-label="${s.category==='lab'?labTestName(s.name):label(s.name)}"><span>${s.category==='lab'?labTestName(s.name):label(s.name)} · ${money(s.price)}</span><input type="number" min="1" max="100" step="1" value="1" data-qty="${esc(s.id)}" aria-label="${t('الكمية','Quantity')}"></div>`).join('')}</div><div class="formgrid"><label>${t('خصم إضافي نقدي — جنيه','Extra cash discount — EGP')}<input name="discount" type="number" min="0" step="0.01" value="0"></label></div><p id="invoice-booked-price" class="sub"></p><div id="quote-output" class="totals"></div><div class="actions">${btn('quote',t('معاينة الحساب','Calculate'),'',true)}<button>${t('اعتماد وترحيل الفاتورة','Post invoice')}</button></div></form>`);setInvoiceCoverage();}
