async function calculate(){quote=await api<Quote>('/api/quote',invoiceData());$('#quote-output').innerHTML=([['الإجمالي قبل الخصم','Gross',quote.gross],['الخصم','Discount',quote.discount],['على المريض','Patient share',quote.patient_due],['على شركة التأمين','Insurer share',quote.insurer_due],['مستحق الطبيب قبل الخصم','Doctor fee before discount',quote.doctor_due],['صافي الفاتورة','Net total',quote.total]] as [string,string,number][]).map(([ar,en,v])=>`<div class="statrow"><span>${t(ar,en)}</span><strong>${money(v)}</strong></div>`).join('');}
