function journalForm(){modal(t('قيد يومية يدوي','Manual journal entry'),`<form id="journal-form">${field('memo','البيان','Description','text',true)}<div id="journal-lines">${journalLine()}${journalLine()}</div><div class="actions">${btn('add-line',t('+ سطر','+ Line'),'',true)}<button>${t('ترحيل قيد متوازن','Post balanced entry')}</button></div></form>`);}
function journalLine(){return `<div class="formgrid journal-line"><label>${t('الحساب','Account')}<select name="account_id">${state.accounts.filter(a=>a.postable).map(a=>`<option value="${esc(a.id)}">${esc(a.id)} · ${label(a.name)}</option>`).join('')}</select></label><div class="formgrid">${field('debit','مدين','Debit','number')}${field('credit','دائن','Credit','number')}</div></div>`;}
function cairoDay(value:string){const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value));const m=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${m.year}-${m.month}-${m.day}`;}
function filteredLines(){const from=document.querySelector<HTMLInputElement>('#report-from')?.value||'',to=document.querySelector<HTMLInputElement>('#report-to')?.value||'';const ids=new Set(state.journals.filter(j=>(!from||cairoDay(j.created_at)>=from)&&(!to||cairoDay(j.created_at)<=to)).map(j=>j.id));return state.lines.filter(l=>ids.has(l.journal_id));}
function trialReport(){const lines=filteredLines();let dr=0,cr=0;const rows=state.accounts.filter(a=>a.postable).map(a=>{const ls=lines.filter(l=>l.account_id===a.id),debit=ls.reduce((s,x)=>s+x.debit,0),credit=ls.reduce((s,x)=>s+x.credit,0);dr+=debit;cr+=credit;return `<tr><td>${esc(a.id)}</td><td>${label(a.name)}</td><td>${money(debit)}</td><td>${money(credit)}</td><td>${money(Math.max(debit-credit,0))}</td><td>${money(Math.max(credit-debit,0))}</td><td>${btn('edit-account',t('تعديل','Edit'),a.id,true)}${btn('delete-account',t('حذف','Delete'),a.id,true)}</td></tr>`;});rows.push(`<tr><td colspan="2"><strong>${t('المجموع','Total')}</strong></td><td>${money(dr)}</td><td>${money(cr)}</td><td colspan="2">${dr===cr?t('متوازن','Balanced'):t('غير متوازن','Unbalanced')}</td><td></td></tr>`);return panel(t('ميزان مراجعة — حركة الفترة وصافيها','Trial balance — period movement & net'),table([t('الكود','Code'),t('الحساب','Account'),t('حركة مدين','Debit movement'),t('حركة دائن','Credit movement'),t('صافي مدين','Net debit'),t('صافي دائن','Net credit'),t('الإجراءات','Actions')],rows));}
function runReport(){const from=$<HTMLInputElement>('#report-from').value,to=$<HTMLInputElement>('#report-to').value;if(from&&to&&from>to)throw Error(t('تاريخ البداية يجب ألا يتجاوز النهاية','Start date must not exceed end date'));const kind=$<HTMLSelectElement>('#report-type').value,ls=filteredLines();let html='';if(kind==='trial')html=trialReport();if(kind==='accounts')html=panel(t('شجرة الحسابات','Chart of accounts'),table([t('الكود','Code'),t('الحساب','Account'),t('الحساب الأب','Parent account'),t('النوع','Type'),t('الإجراءات','Actions')],state.accounts.map(a=>`<tr><td>${a.id}</td><td>${label(a.name)}</td><td>${esc(a.parent_id)||'—'}</td><td>${a.postable?t('تفصيلي','Posting'):t('تجميعي','Group')}</td><td>${btn('edit-account',t('تعديل','Edit'),a.id,true)}${btn('delete-account',t('حذف','Delete'),a.id,true)}</td></tr>`)));if(kind==='ledger')html=panel(t('الأستاذ العام','General ledger'),table([t('التاريخ','Date'),t('الحساب','Account'),t('البيان','Description'),t('مدين','Debit'),t('دائن','Credit'),t('المستند','Source')],ls.map(l=>{const j=state.journals.find(x=>x.id===l.journal_id)!;return `<tr><td>${dt(j.created_at)}</td><td>${esc(l.account_id)} · ${label(state.accounts.find(a=>a.id===l.account_id)?.name)}</td><td>${label(j.memo)}</td><td>${money(l.debit)}</td><td>${money(l.credit)}</td><td>${esc(j.source_id.slice(0,8))}</td></tr>`;})));if(kind==='income'){let net=0;const rows=state.accounts.filter(a=>['revenue','contra_revenue','expense'].includes(a.category)).map(a=>{const val=ls.filter(l=>l.account_id===a.id).reduce((s,l)=>s+l.credit-l.debit,0);net+=val;return `<tr><td>${label(a.name)}</td><td>${money(val)}</td></tr>`;});rows.push(`<tr><td><strong>${t('صافي نتيجة الفترة','Net result for period')}</strong></td><td><strong>${money(net)}</strong></td></tr>`);html=panel(t('الإيرادات والمصروفات — ليست قائمة نظامية نهائية','Income & expenses — preliminary report'),table([t('الحساب','Account'),t('صافي الأثر على النتيجة','Net effect on result')],rows));}if(kind==='audit')html=panel(t('سجل العمليات','Audit trail'),table([t('الوقت','Time'),t('المستخدم','User'),t('العملية','Action'),t('المرجع','Reference')],state.audit.filter(a=>(!from||cairoDay(a.created_at)>=from)&&(!to||cairoDay(a.created_at)<=to)).map(a=>`<tr><td>${dt(a.created_at)}</td><td>${esc(a.user_id)}</td><td>${esc(a.action)}</td><td>${esc(a.entity_id.slice(0,8))}</td></tr>`)));html=html.replace(t('لا توجد بيانات بعد. ابدأ بإضافة أول سجل.','No records yet. Add your first record to begin.'),t('لا توجد سجلات مطابقة للتقرير والفترة المحددة.','No matching records for this report and period.'));if(!html)throw Error(t('اختر تقريرًا صالحًا','Choose a valid report'));$('#report-output').innerHTML=`<p class="report-feedback" role="status">${kind==='accounts'?t('شجرة الحسابات الحالية — لا تتغير بالفترة','Current chart of accounts — independent of period'):t('تم عرض التقرير','Report displayed')} · ${esc(from||t('البداية','Beginning'))} — ${esc(to||t('حتى الآن','To date'))}</p>`+html;notify(t('تم تحديث التقرير حسب الفترة المحددة','Report updated for the selected dates'));}
function printDocument(title:string,body:string,patient='',time=''){const facility=esc(state.settings.facility);$('#print-area').innerHTML=`<header><div>${state.settings.logo?`<img class="print-logo" src="${esc(state.settings.logo)}" alt="${facility}">`:''}<h1>${facility}</h1><span>MADAR MEDICAL</span></div><div>${label(state.branches.find(x=>x.id===branch)?.name)}<br>${esc(time||dt(new Date().toISOString()))}</div></header><h2>${title}</h2>${demoMode?`<p>${t('نسخة تجريبية — ليست مستندًا طبيًا معتمدًا','Demo copy — not an approved clinical document')}</p>`:''}${patient?`<p>${t('المريض','Patient')}: <strong>${esc(patient)}</strong></p>`:''}${body}<footer>${t('اسم وتوقيع المسؤول: ................................','Responsible clinician / officer: ................................')}</footer>`;const images=[...document.querySelectorAll<HTMLImageElement>('#print-area img')];if(images.some(img=>img.complete&&!img.naturalWidth))return notify(t('تعذر تحميل صورة للمطبوع؛ أعد المحاولة','A report image failed to load; retry printing'),true);const pending=images.filter(img=>!img.complete);if(pending.length)void Promise.all(pending.map(img=>new Promise<boolean>(resolve=>{const timer=setTimeout(()=>resolve(false),10000);img.onload=()=>{clearTimeout(timer);resolve(true);};img.onerror=()=>{clearTimeout(timer);resolve(false);};}))).then(ok=>ok.every(Boolean)?window.print():notify(t('تعذر تحميل صور المطبوع؛ تحقق من الاتصال وأعد المحاولة','Report images could not load; check connection and retry'),true));else window.print();}
function printVisit(id:string,type:string){if(state.user.role!=='doctor')return notify(t('المطبوعات الطبية للطبيب المعالج فقط','Clinical printouts are restricted to the treating doctor'),true);const v=state.visits.find(x=>x.id===id);if(!v)return;const d=JSON.parse(v.payload) as VisitNotes,p=state.patients.find(x=>x.id===v.patient_id),meta=v.link?JSON.parse(v.link.details) as BookingDetails:undefined;const fields:Record<string,[string,string]>={complaint:['الشكوى','Complaint'],diagnosis:['التشخيص','Diagnosis'],examination:['الفحص والملاحظات','Examination & findings'],treatment:['الخطة العلاجية','Treatment plan'],prescription:['وصفة الأدوية','Medication prescription'],lab_request:['طلب تحاليل','Laboratory request'],radiology_request:['طلب أشعة','Radiology request'],follow_up:['المتابعة والتعليمات','Follow-up instructions']};const kind:Record<string,string>={prescription:'prescription',lab:'lab_request',radiology:'radiology_request'},keys=type==='summary'?Object.keys(fields):[kind[type]||'prescription'];const title=type==='summary'?t('ملخص الزيارة','Visit summary'):t(...fields[keys[0]]);if(type!=='summary'&&!String(d[keys[0] as keyof VisitNotes]||'').trim())return notify(t('لم يسجل الطبيب محتوى لهذا الطلب','No content recorded for this document'),true);const content=(key:string)=>key==='lab_request'&&d.lab_orders?.length?'<article>'+d.lab_orders.map(x=>labTestName(x.name)).join('<br>')+'</article>':key==='prescription'&&d.prescriptions?.length?table([t('الدواء','Medicine'),t('التركيز','Strength'),t('الجرعة','Dose'),t('الطريقة','Route'),t('التكرار','Frequency'),t('المدة','Duration')],d.prescriptions.map(x=>`<tr><td class="wrap">${label(x.name)}</td><td>${esc(x.strength)||'—'}</td><td>${esc(x.dose)}</td><td>${esc(x.route)}</td><td>${esc(x.frequency)}</td><td>${esc(x.duration)}</td></tr>`)):`<article>${esc(d[key as keyof VisitNotes])||'—'}${key==='diagnosis'&&d.diagnosis_notes?'\n'+esc(d.diagnosis_notes):''}</article>`;const body=`<p>${t('الطبيب','Doctor')}: ${esc(meta?.doctor_name||doctorName(v.doctor_id))} · ${t('نوع الزيارة','Visit type')}: ${visitType(v.link?.visit_type)}</p>${meta?`<p>${t('العيادة','Clinic')}: ${label(meta.clinic_name)} · ${t('التخصص','Specialty')}: ${label(meta.specialty_name)}</p>`:''}<p>${t('العمر وقت الكشف','Age at examination')}: ${d.patient_age_years??p?.age_years??'—'} · ${t('الحساسية المسجلة','Recorded allergies')}: ${esc(d.allergies??p?.allergies)||t('غير مسجلة','Not documented')}</p>${keys.map(k=>`<h2>${t(...fields[k])}</h2>${content(k)}`).join('')}`;printDocument(title,body,d.patient_name||patientName(v.patient_id),dt(v.created_at));}

function printInvoice(id:string){const d=state.documents.find(x=>x.id===id)!,q=JSON.parse(d.payload) as Quote;printDocument(t('فاتورة خدمات','Service invoice'),`<p>${t('رقم المستند','Document ID')}: ${esc(d.id)} · ${d.status==='returned'?t('مرتجعة','Returned'):t('مرحلة','Posted')}</p>${table([t('الخدمة','Service'),t('الكمية','Qty'),t('الإجمالي','Total'),t('المريض','Patient'),t('التأمين','Insurer')],q.items.map(i=>`<tr><td>${label(i.name)}</td><td>${i.qty}</td><td>${money(i.total)}</td><td>${money(i.patient_due)}</td><td>${money(i.insurer_due)}</td></tr>`))}<p>${t('خصم إضافي','Extra discount')}: ${money(q.discount)}<br>${t('الصافي','Net total')}: <strong>${money(d.total)}</strong><br>${t('مطلوب من المريض بعد الخصم','Patient share after discount')}: ${money(d.patient_due)}<br>${t('مطلوب من الشركة','Insurer share')}: ${money(d.insurer_due)}</p>`,patientName(d.party),dt(d.created_at));}
function exportReport(){const rows=[...$('#report-output').querySelectorAll('tr')].map(tr=>[...tr.children].map(td=>'"'+td.textContent.replace(/"/g,'""').replace(/^[\s\u200e\u200f]*[=+@-]/,"'$&")+'"').join(','));const blob=new Blob(['\ufeff'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Madar-'+branch+'-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',async e=>{const target=(e.target as HTMLElement).closest('button');if(!target)return;try{if(target.dataset.page){page=target.dataset.page;render();return;}const action=target.dataset.action,id=target.dataset.id||'';if(!action)return;if(await workflowAction(action,id,target))return;if(action==='select-role'){selectedRole=id as Role;login();}if(action==='setup')setupForm();if(action==='new-user')userForm();if(action==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;}if(action==='language'){lang=lang==='ar'?'en':'ar';localStorage.setItem('madar-language',lang);state?render():login();}if(action==='logout'){await api('/api/logout',{});state=undefined!;users=[];quote=undefined;closeModal();$('#print-area').innerHTML='';login();}if(action==='close-modal')closeModal();if(action==='new-patient')patientForm();if(action==='new-visit')visitForm();if(action==='new-invoice')invoiceForm();if(action==='quote')await calculate();if(action==='payment')paymentForm(id);if(action==='return'){modal(t('تأكيد المردود الكامل','Confirm full return'),`<p>${t('يعكس القيد ومستحق الطبيب. متاح فقط للفواتير غير المحصلة.','Reverses the posting and doctor entitlement. Only available for unpaid invoices.')}</p>${btn('confirm-return',t('تأكيد المردود','Confirm return'),id)}`);}if(action==='confirm-return'){await api('/api/returns',{document_id:id});closeModal();await load();notify(t('تم المردود وعكس القيد','Returned and reversed'));}if(action==='new-account')accountForm();if(action==='new-journal')journalForm();if(action==='add-line')$('#journal-lines').insertAdjacentHTML('beforeend',journalLine());if(action==='run-report')runReport();if(action==='export-report')exportReport();if(action==='print-report')printDocument(t('تقرير حسابات','Accounting report'),$('#report-output').innerHTML);if(action==='print-invoice')printInvoice(id);if(action.startsWith('visit-'))printVisit(id,action.slice(6));}catch(err){notify(err instanceof Error?err.message:String(err),true);}});
document.addEventListener('change',async e=>{workflowChange(e.target as HTMLInputElement);const target=e.target as HTMLInputElement;if(target.id==='login-role-select'){selectedRole=target.value as Role;login();return;}if(target.id==='branch-select'){const previous=branch;branch=target.value;closeModal();try{await load();}catch(err){branch=previous;render();notify(err instanceof Error?err.message:String(err),true);}}if((e.target as HTMLElement).closest('#invoice-form')&&(e.target as HTMLInputElement).name==='plan_id'){const f=$<MedicalForm>('#invoice-form');control(f,'discount').value='0';control(f,'discount').disabled=!!(e.target as HTMLInputElement).value;$('#quote-output').innerHTML='';}if((e.target as HTMLElement).closest('#invoice-form')&&$('#quote-output'))$('#quote-output').innerHTML='';});
document.addEventListener('input',e=>{if((e.target as HTMLInputElement).name==='birth_date')updateAge();if((e.target as HTMLElement).id==='patient-search'){const val=(e.target as HTMLInputElement).value.toLowerCase();document.querySelectorAll<HTMLTableRowElement>('tbody tr').forEach(tr=>tr.hidden=!(tr.textContent||'').toLowerCase().includes(val));}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as MedicalForm,button=f.querySelector<HTMLButtonElement>('button[type=submit],button:not([type])');if(button)button.disabled=true;try{const data:Record<string,unknown>=Object.fromEntries(new FormData(f));if('record_id' in data){data.id=data.record_id;delete data.record_id;}clearFormError(f);if(f.getAttribute('id')==='doctor-search'){updateDoctorSearch();return;}if(await workflowSubmit(f,data))return;if(f.getAttribute('id')==='login-form'){const r=await api<{branch:string;role:Role}>('/api/login',data);branch=r.branch;page=r.role==='doctor'?'visits':r.role==='accountant'?'accounting':r.role==='reception'?'bookings':r.role==='lab'?'lab-work':r.role==='radiology'?'radiology-work':'dashboard';await load();return;}if(f.getAttribute('id')==='setup-form'){await api('/api/setup',data);setupRequired=false;closeModal();login();notify(t('تم إنشاء المدير. سجل الدخول.','Administrator created. Please sign in.'));return;}let endpoint;if(f.getAttribute('id')==='user-form')endpoint='/api/users';if(f.getAttribute('id')==='patient-form')endpoint='/api/patients';if(f.getAttribute('id')==='visit-form'){endpoint='/api/visits';data.branch_id=branch;}if(f.getAttribute('id')==='invoice-form'){await calculate();const payload=invoiceData();await api('/api/invoices',payload,formKey(f,payload));closeModal();await load();notify(t('تم ترحيل الفاتورة والقيد','Invoice and journal posted'));return;}if(f.getAttribute('id')==='payment-form'){endpoint='/api/receipts';data.document_id=f.dataset.id;}if(f.getAttribute('id')==='journal-form'){endpoint='/api/journals';data.branch_id=branch;data.lines=[...f.querySelectorAll<HTMLElement>('.journal-line')].map(el=>({account_id:el.querySelector<HTMLSelectElement>('[name=account_id]')!.value,debit:el.querySelector<HTMLInputElement>('[name=debit]')!.value||0,credit:el.querySelector<HTMLInputElement>('[name=credit]')!.value||0}));}if(f.getAttribute('id')==='account-form'){endpoint='/api/accounts';data.group=control(f,'group').checked;}if(f.getAttribute('id')==='settings-form'){endpoint='/api/settings';data.logo=await chosenLogo(f);}if(!endpoint)throw Error(t('تعذر تحديد نموذج الحفظ. أغلقه وأعد فتحه.','Cannot identify this form. Close and reopen it.'));await api(endpoint,data,formKey(f,data));closeModal();await load();notify(t('تم الحفظ بنجاح','Saved successfully'));}catch(err){const message=err instanceof Error?err.message:String(err);showFormError(f,message);notify(message,true);}finally{if(button)button.disabled=false;}});

function accountForm(id=''){const a=state.accounts.find(x=>x.id===id);modal(a?t('تعديل حساب','Edit account'):t('إضافة حساب','Add account'),`<form id="account-form"><input type="hidden" name="record_id" value="${esc(id)}"><div class="formgrid"><label>${t('كود الحساب — تلقائي حسب الأب','Account code — automatic under parent')}<input readonly value="${esc(a?.id||t('يولد عند الحفظ ولا يعاد استخدامه','Generated on save, never reused'))}"></label>${field('name','اسم الحساب — عربي / English','Account name — Arabic / English','text',true)}<label>${t('الحساب الأب','Parent account')}<select name="parent_id" ${a?'disabled':''}>${a?`<option value="${esc(a.parent_id)}">${label(state.accounts.find(x=>x.id===a.parent_id)?.name)||'—'}</option>`:options(state.accounts.filter(a=>!a.postable))}</select></label><label>${t('حساب تجميعي؟','Group account?')}<input type="checkbox" name="group" ${a&&!a.postable?'checked':''}></label></div><div class="actions"><button>${t('حفظ الحساب','Save account')}</button></div></form>`);if(a)control($<MedicalForm>('#account-form'),'name').value=a.name;}


function formKey(form:MedicalForm,data:unknown){const fingerprint=JSON.stringify(data);if(form._fingerprint!==fingerprint){form._fingerprint=fingerprint;form._requestKey=requestId();}return form._requestKey!;}

