function setupForm(){modal(t('تهيئة المدير','Administrator setup'),`<form id="setup-form"><div class="formgrid">${field('token','رمز التهيئة الظاهر في نافذة الخادم','Setup token shown in server console','text',true)}${field('username','اسم المستخدم للمدير','Administrator username','text',true)}${field('password','كلمة مرور ٤ أحرف أو أرقام على الأقل','Password, at least 4 characters','password',true)}</div><div class="actions"><button>${t('إنشاء المدير','Create administrator')}</button></div></form>`);}
function branchChecks(selected:string[]=[]){return `<fieldset class="full"><legend>${t('الفروع المسموح بها — يمكن اختيار أكثر من فرع','Allowed branches — select one or more')}</legend><div class="row">${state.branches.map(b=>`<label class="check"><input type="checkbox" name="branch_ids" value="${esc(b.id)}" ${selected.includes(b.id)?'checked':''}>${label(b.name)}</label>`).join('')}</div></fieldset>`;}
function permissionMatrix(p:Permissions){return `<div class="scroll full"><table class="permission-matrix"><thead><tr><th>${t('الشاشة','Screen')}</th>${[['view','دخول / عرض','View'],['add','إضافة','Add'],['edit','تعديل','Edit'],['delete','حذف','Delete']].map(x=>`<th>${t(x[1],x[2])}</th>`).join('')}</tr></thead><tbody>${screens.map(key=>{const n=nav.find(x=>x[0]===key)!;return `<tr><td>${t(n[2],n[3])}</td>${(['view','add','edit','delete'] as const).map(a=>`<td><input type="checkbox" data-permission="${key}" data-operation="${a}" ${p[key][a]?'checked':''} aria-label="${t(n[2],n[3])} ${a}"></td>`).join('')}</tr>`;}).join('')}</tbody></table></div>`;}
function userForm(id=''){const u=users.find(x=>x.id===id),role=u?.role||'reception';modal(u?t('تعديل حساب الموظف','Edit staff account'):t('حساب موظف جديد','New staff account'),`<form id="user-form"><input type="hidden" name="record_id" value="${esc(id)}"><div class="formgrid">${field('display_name','الاسم الكامل للموظف / الطبيب','Staff / doctor full name','text',true)}${field('username','اسم المستخدم — حروف إنجليزية وأرقام','Username — letters and numbers','text',true)}${field('password',u?'كلمة مرور جديدة — اتركها فارغة للإبقاء عليها':'كلمة المرور — ٤ أحرف أو أرقام على الأقل',u?'New password — leave blank to keep current':'Password — at least 4 characters','password',!u)}<label>${t('الدور','Role')}<select name="role" id="staff-role">${Object.entries(roles).map(([key,value])=>`<option value="${key}" ${key===role?'selected':''}>${t(...value)}</option>`).join('')}</select></label>${branchChecks(u?.branch_ids||[u?.branch_id||branch])}</div><p class="sub">${t('المدير يصل للفروع المسموحة بالخادم. تفاصيل الكشف للطبيب المعالج فقط. إدارة المستخدمين والإعدادات للمدير. تغيير الدور يعيد الصلاحيات الافتراضية ويمكن تعديلها قبل الحفظ.','Administrators access server-allowed branches. Clinical notes remain restricted to the treating doctor. Users and settings require an administrator. Changing role resets the editable permission defaults.')}</p><div id="staff-permissions">${permissionMatrix(u?.permissions||defaultPermissions(role))}</div><div class="actions"><button>${t('حفظ الحساب','Save account')}</button></div></form>`);if(u){const f=$<MedicalForm>('#user-form');control(f,'display_name').value=u.display_name||u.username;control(f,'username').value=u.username;}}
