 views.patients=()=>{const items=showArchived?state.archived_patients:state.patients;return head(t('ملفات المرضى','Patient records'),t('العمر يُحسب من تاريخ الميلاد • بيانات السداد ومصدر التعارف','Age from birth date • payer and referral details'),`<div class="row">${btn('toggle-archived',showArchived?t('المرضى النشطون','Active patients'):t('الملفات المحذوفة','Deleted files'),'',true)}${btn('new-patient',t('+ مريض جديد','+ New patient'))}</div>`)+panel(t('دليل المرضى','Patient directory'),table([t('المريض','Patient'),t('الهاتف','Phone'),t('الميلاد / العمر','Birth / age'),t('السداد','Payer'),t('التعارف على المركز','Referral source'),t('الإجراءات','Actions')],items.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.phone)}</td><td>${esc(p.birth_date)||'—'}<br><strong>${p.age_years??ageYears(p.birth_date)??'—'} ${p.birth_date?t('سنة','years'):''}</strong></td><td>${p.payer_type==='insurance'?`<span class="badge">${t('تأمين','Insurance')}</span><br>${label(catalogName('insurance_companies',p.insurer_id||''))}<br><small>${label(state.plans.find(x=>x.id===p.plan_id)?.name)}</small>`:t('عادي / خاص','Private / cash')}</td><td>${label(catalogName('referral_sources',p.referral_source_id||''))||'—'}<br><small>${esc(p.referral_notes)}</small></td><td>${showArchived?btn('restore-patient',t('استعادة','Restore'),p.id):btn('edit-patient',t('تعديل','Edit'),p.id,true)+btn('delete-patient',t('حذف','Delete'),p.id,true)}${btn('print-patient',t('طباعة المعلومات','Print information'),p.id,true)}</td></tr>`)),`<input class="search" id="patient-search" placeholder="${t('بحث بالاسم أو الهاتف','Search name or phone')}" aria-label="${t('بحث المرضى','Search patients')}">`);};
