function catalogForm(id=''){const item=state.catalogs[catalogKind].find(x=>x.id===id);modal(`${item?t('تعديل','Edit'):t('إضافة','Add')} — ${t(...catalogLabels[catalogKind])}`,`<form id="catalog-form"><input type="hidden" name="record_id" value="${esc(id)}"><input type="hidden" name="kind" value="${catalogKind}"><div class="formgrid">${catalogKind==='lab_tests'?field('name_en','اسم التحليل بالإنجليزية — أساسي','Test name in English — primary','text',true)+field('name_ar','اسم التحليل بالعربية','Test name in Arabic','text',true):field('name','الاسم — عربي / English','Name — Arabic / English','text',true)}<label>${t('الكود — تلقائي ولا يعاد استخدامه','Code — automatic, never reused')}<input name="code" readonly placeholder="${t('يولد عند الحفظ','Generated on save')}"></label>${['lab_tests','radiology_tests'].includes(catalogKind)?`<label class="full">${t('خدمة التسعير المرتبطة — اختيارية','Linked priced service — optional')}<select name="service_id"><option value="">${t('بدون ربط','Not linked')}</option>${options(state.services.filter(s=>s.active!==0&&s.category===(catalogKind==='lab_tests'?'lab':'radiology')))}</select>${can('services')?btn('manage-services',t('فتح شاشة الخدمات والأسعار','Open services & prices'),'',true):''}<small>${t('أنشئ خدمة من نوع معمل أو أشعة أولًا ثم اربطها هنا.','First create a lab or radiology service, then link it here.')}</small></label>`:''}</div><div class="actions"><button>${t('حفظ','Save')}</button></div></form>`);if(item){const f=$<MedicalForm>('#catalog-form');if(catalogKind==='lab_tests'){const parts=item.name.split(' / ');control(f,'name_en').value=parts.find(x=>/[A-Za-z]/.test(x))||'';control(f,'name_ar').value=parts.filter(x=>/[\u0600-\u06ff]/.test(x)).join(' / ');}else control(f,'name').value=item.name;control(f,'code').value=item.code;if(f.elements.namedItem('service_id'))control(f,'service_id').value=item.service_id;}}
function planForm(id=''){const p=state.plans.find(x=>x.id===id),r=p?JSON.parse(p.payload) as PlanRules:undefined;modal(t('تعاقد وأسعار التأمين','Insurance contract & prices'),`<form id="plan-form"><input type="hidden" name="record_id" value="${esc(id)}"><div class="formgrid">${field('name','اسم الخطة / التعاقد','Plan / contract name','text',true)}<label>${t('الشركة','Company')}<select name="insurer_id" required>${options(activeCatalog('insurance_companies'))}</select></label>${field('valid_from','بداية السريان','Valid from','date',true)}${field('valid_to','نهاية السريان','Valid to','date',true)}</div><p class="sub">${t('اختر الخدمات المغطاة وحدد سعر التعاقد ونسبة تحمل المريض لكل خدمة','Select covered services, contract price and patient copayment for each service')}</p><div class="scroll"><table><thead><tr><th>${t('مغطاة','Covered')}</th><th>${t('الخدمة','Service')}</th><th>${t('السعر بالجنيه','Price in EGP')}</th><th>${t('تحمل المريض ٪','Patient share %')}</th></tr></thead><tbody>${state.services.filter(s=>s.active!==0).map(s=>`<tr class="plan-rate" data-service="${esc(s.id)}"><td><input name="covered" type="checkbox" ${r?.rates[s.id]?'checked':''} aria-label="${s.category==='lab'?labTestName(s.name):label(s.name)}"></td><td>${s.category==='lab'?labTestName(s.name):label(s.name)}</td><td><input name="price" type="number" min="0" step="0.01" value="${(r?.rates[s.id]?.[0]??s.price)/100}" aria-label="${t('السعر','Price')}"></td><td><input name="patient_percent" type="number" min="0" max="100" step="0.01" value="${(r?.rates[s.id]?.[1]??2000)/100}" aria-label="${t('نسبة التحمل','Copayment')}"></td></tr>`).join('')}</tbody></table></div><div class="actions"><button>${t('حفظ التعاقد','Save contract')}</button></div></form>`);const f=$<MedicalForm>('#plan-form');if(p&&r){control(f,'name').value=p.name;control(f,'insurer_id').value=r.insurer_id||'';control(f,'valid_from').value=r.valid_from;control(f,'valid_to').value=r.valid_to;}else{control(f,'valid_from').value=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo'}).format(new Date());control(f,'valid_to').value='2027-12-31';}}
function setInvoiceCoverage(){const f=document.querySelector<HTMLFormElement>('#invoice-form');if(!f)return;const v=state.visits.find(x=>x.id===control(f,'visit_id').value),details=v?.link?JSON.parse(v.link.details) as BookingDetails:undefined;f.querySelectorAll<HTMLInputElement>('[name=service]').forEach(x=>{x.checked=x.value===details?.tariff?.service_id;});for(const row of f.querySelectorAll<HTMLElement>('.checkrow')){const sid=row.querySelector<HTMLInputElement>('[name=service]')!.value,s=state.services.find(s=>s.id===sid)!,span=row.querySelector('span')!;const tariff=details?.tariff;const plan=details?.plan_id?state.plans.find(p=>p.id===details.plan_id):undefined;const rate=plan?(JSON.parse(plan.payload) as PlanRules).rates[sid]:undefined;const price=tariff?.service_id===sid?(tariff.contract_price??tariff.price):(rate?.[0]??s.price);span.innerHTML=(s.category==='lab'?labTestName(s.name):label(s.name))+' · '+money(price);}const hint=f.querySelector<HTMLElement>('#invoice-booked-price');if(hint)hint.textContent=details?.tariff?t('تم اختيار خدمة الحجز تلقائيًا؛ المعاينة تستخدم السعر المحفوظ ونسبة الطبيب.','Booked service selected automatically; calculation uses saved pricing and doctor share.'):'';const plan=control(f,'plan_id');if(details){plan.value=details.plan_id;plan.disabled=true;}else{plan.disabled=false;}control(f,'discount').value='0';control(f,'discount').disabled=!!plan.value;}
function workflowChange(target:HTMLInputElement){if(target.name==='image_files'){void previewImages(target);return;}if(target.name==='unit'&&target.closest('#result-form .lab-result-row')){const row=target.closest('.lab-result-row')!;row.querySelector<HTMLInputElement>('[name=reference]')!.value='';row.querySelector<HTMLSelectElement>('[name=flag]')!.value='unspecified';}if(target.id==='external-department'){externalChoices();return;}if(target.classList.contains('measurement-select')){const row=target.closest('.lab-result-row')!,q=state.service_requests?.find(q=>q.id===$<HTMLInputElement>('#result-form [name=request_id]').value),definition=q?definitionFor(q):undefined,chosen=definition?.rows.find(r=>r.parameter===target.value);if(chosen){row.querySelector<HTMLInputElement>('[name=parameter]')!.value=chosen.parameter;row.querySelector<HTMLInputElement>('[name=unit]')!.value=chosen.unit;row.querySelector<HTMLInputElement>('[name=reference]')!.value=chosen.reference;row.querySelector<HTMLInputElement>('[name=value]')!.value='';row.querySelector<HTMLSelectElement>('[name=flag]')!.value='unspecified';}return;}if(target.closest('#doctor-search')){updateDoctorSearch();return;}if(['report-type','report-from','report-to'].includes(target.id)){try{runReport();}catch(e){notify(e instanceof Error?e.message:String(e),true);}return;}if(target.closest('#settings-form')&&['theme','skin'].includes(target.name))document.documentElement.setAttribute('data-'+target.name,target.value);if(target.id==='doctor-account'){const block=$('#doctor-new-account'),existing=!!target.value;block.hidden=existing;block.querySelectorAll<HTMLInputElement>('input').forEach(x=>{x.disabled=existing;});return;}if(target.id==='staff-role'){$('#staff-permissions').innerHTML=permissionMatrix(defaultPermissions(target.value as Role));return;}if(target.id==='catalog-kind'){catalogKind=target.value as CatalogKind;render();return;}if(target.closest('#patient-form')&&['payer_type','insurer_id'].includes(target.name))updatePatientInsurance();if(target.id==='booking-clinic')updateBookingDoctors();if(target.closest('#booking-form')&&target.name==='patient_id')updateBookingCoverage();if(target.closest('#booking-form'))updateBookingPrice();if(target.id==='invoice-visit')setInvoiceCoverage();}
async function workflowSubmit(f:MedicalForm,data:Record<string,unknown>):Promise<boolean>{let endpoint='';if(f.getAttribute('id')==='exam-definition-form'){endpoint='/api/exam-definitions';data.published_adult=control(f,'adult_reference').checked;data.rows=[...f.querySelectorAll<HTMLElement>('.definition-row')].map(row=>Object.fromEntries(['id','parameter','unit','reference'].map(k=>[k,k==='id'?row.dataset.parameterId||'':row.querySelector<HTMLInputElement>('[name='+k+']')!.value])));}if(f.getAttribute('id')==='external-form'){endpoint='/api/external-services';data.branch_id=branch;data.tests=[...f.querySelectorAll<HTMLInputElement>('[name=external_test]:checked')].map(x=>x.value);data.scheduled_at=cairoDateTimeToISO(String(data.scheduled_local));}if(f.getAttribute('id')==='result-form'||f.getAttribute('id')==='review-result-form'){endpoint='/api/results';data.id=data.request_id;delete data.request_id;data.version=Number(data.version);if(f.getAttribute('id')==='result-form'){const q=state.service_requests!.find(q=>q.id===data.id)!;if(q.department==='radiology')await uploadResultImages(f,q.id);data.result=q.department==='lab'?{rows:[...f.querySelectorAll<HTMLElement>('.lab-result-row')].map(row=>Object.fromEntries(['parameter_id','parameter','value','unit','reference','flag'].map(k=>[k,k==='parameter_id'?row.dataset.parameterId||'':row.querySelector<HTMLInputElement|HTMLSelectElement>('[name='+k+']')!.value]))),notes:data.notes,reference_context:definitionFor(q).reference_context}:{findings:data.findings,impression:data.impression,recommendations:data.recommendations};}}if(f.getAttribute('id')==='tariff-form'){endpoint='/api/tariffs';data.rates=[...f.querySelectorAll<HTMLElement>('.tariff-row')].filter(row=>row.querySelector<HTMLInputElement>('[name=enabled]')!.checked).map(row=>({visit_type:row.dataset.type,service_id:row.querySelector<HTMLSelectElement>('[name=service_id]')!.value,price:row.querySelector<HTMLInputElement>('[name=price]')!.value,doctor_percent:row.querySelector<HTMLInputElement>('[name=doctor_percent]')!.value}));}if(f.getAttribute('id')==='service-form')endpoint='/api/services';if(f.getAttribute('id')==='doctor-form'){endpoint='/api/doctors';data.branch_ids=[...f.querySelectorAll<HTMLInputElement>('[name=branch_ids]:checked')].map(x=>x.value);if(data.id&&!f.elements.namedItem('username'))delete data.branch_ids;if(f.querySelector('[data-permission]')){const permissions=defaultPermissions('doctor');for(const x of f.querySelectorAll<HTMLInputElement>('[data-permission]'))permissions[x.dataset.permission as Screen][x.dataset.operation as AccessAction]=x.checked;data.permissions=permissions;}}if(f.getAttribute('id')==='user-form'){endpoint='/api/users';data.branch_ids=[...f.querySelectorAll<HTMLInputElement>('[name=branch_ids]:checked')].map(x=>x.value);const permissions=defaultPermissions(control(f,'role').value as Role);for(const input of f.querySelectorAll<HTMLInputElement>('[data-permission]'))permissions[input.dataset.permission as Screen][input.dataset.operation as AccessAction]=input.checked;data.permissions=permissions;}if(f.getAttribute('id')==='booking-form'){endpoint='/api/appointments';data.branch_id=branch;data.scheduled_at=cairoDateTimeToISO(control(f,'scheduled_local').value);delete data.scheduled_local;delete data.clinic_id;}if(f.getAttribute('id')==='clinic-form'){endpoint='/api/clinics';data.branch_id=branch;}if(f.getAttribute('id')==='assignment-form'){endpoint='/api/assignments';data.branch_id=branch;}if(f.getAttribute('id')==='catalog-form')endpoint='/api/catalogs';if(f.getAttribute('id')==='plan-form'){endpoint='/api/plans';data.rates=[...f.querySelectorAll<HTMLElement>('.plan-rate')].filter(el=>el.querySelector<HTMLInputElement>('[name=covered]')!.checked).map(el=>({service_id:el.dataset.service,price:el.querySelector<HTMLInputElement>('[name=price]')!.value,patient_percent:el.querySelector<HTMLInputElement>('[name=patient_percent]')!.value}));}if(f.getAttribute('id')==='visit-form'){endpoint='/api/visits';data.prescriptions=[...f.querySelectorAll<HTMLElement>('.prescription-row')].map(el=>Object.fromEntries(['medicine_id','strength','dose','route','frequency','duration'].map(k=>[k,el.querySelector<HTMLInputElement|HTMLSelectElement>(`[name=${k}]`)!.value])));data.lab_ids=[...f.querySelectorAll<HTMLInputElement>('[name=lab_ids]:checked')].map(x=>x.value);data.radiology_ids=[...f.querySelectorAll<HTMLInputElement>('[name=radiology_ids]:checked')].map(x=>x.value);for(const k of ['medicine_id','strength','dose','route','frequency','duration'])delete data[k];}
 if(!endpoint)return false;const saved=await api<{id?:string}>(endpoint,data,formKey(f,data));closeModal();await load();if(endpoint==='/api/visits'&&saved.id)visitPrintActions(saved.id);notify(t('تم الحفظ بنجاح','Saved successfully'));return true;
}
